INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('b1-426', 'vocabulary', 'etwas', 'unspecified thing or minor degree', 'something / a little / anything', '{"de":"Ich muss dir etwas erzählen. / Ich habe nur Tee. Etwas anderes kann ich Ihnen leider nicht anbieten. / Haben Sie etwas zum Schreiben? / Wollen wir mit dem Nachtisch noch etwas warten? / So etwas habe ich noch nie gehört. / Ich habe etwas Gutes für dich gekocht.","en":"I have to tell you something. / I only have tea. Unfortunately I cannot offer you anything else. / Do you have something to write with? / Shall we wait a little with dessert? / I have never heard such a thing. / I cooked something nice for you."}', '["B1"]', 'pronoun', '{"nativeFrequencyRating":5,"nativeFrequencyLabel":"very high","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"standard","regionalLabels":[]}', '[]', '["quantifier;pronoun"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":"etwas anderes; so etwas"},"valency":[{"role":"object","preposition":"ein wenig","case":null},{"role":"object","preposition":"ein bisschen","case":null}],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["nichts"]', '{"synonyms":[],"antonyms":[],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":427,"url":"https://www.goethe.de"}', 'draft');
