INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('b1-855', 'phrase', 'leid tun', 'cause sympathetic sorrow or formal apology', 'to be sorry / to regret', '{"de":"Die Frau tut mir leid. / Wie komme ich zum Bahnhof? - Tut mir leid, das weiß ich nicht. / Es tut mir leid, dass ich Ihnen nicht helfen kann.","en":"I feel sorry for the woman. / How do I get to the station? - I am sorry; I don''t know that. / I am sorry that I cannot help you."}', '["B1"]', 'phrase', '{"nativeFrequencyRating":5,"nativeFrequencyLabel":"very high","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"standard","regionalLabels":[]}', '[]', '["courtesy;emotions"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":null,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[{"role":"object","preposition":null,"case":"dat"}],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["es tut mir leid"]', '{"synonyms":["bedauern; leidtun"],"antonyms":[],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":856,"url":"https://www.goethe.de"}', 'draft');
