INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('b1-869', 'vocabulary', 'lieb', 'gentle', 'dear', '{"de":"or sweet, dear / sweet / kind / good, Die Kinder waren heute sehr lieb. / Vielen Dank für deine Hilfe. Das ist sehr lieb von dir. / Liebe Frau Meier!","en":"The children were very well-behaved today. / Many thanks for your help. That is very kind of you. / Dear Ms. Meier!"}', '["B1"]', 'adjective', '{"nativeFrequencyRating":5,"nativeFrequencyLabel":"very high","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"standard","regionalLabels":[]}', '[]', '["courtesy;personality"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":null,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[{"role":"object","preposition":"liebe Grüße","case":null},{"role":"object","preposition":"sehr lieb von dir","case":null}],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["herzlich; nett; artig"]', '{"synonyms":["böse; gemein"],"antonyms":[],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":870,"url":"https://www.goethe.de"}', 'draft');
INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('b1-87', 'vocabulary', 'aufregen', 'agitate / upset emotionally', 'to upset / to excite / to agitate', '{"de":"Es regt mich auf, dass ich schon wieder Überstunden machen muss. / Ganz ruhig! Bitte regen Sie sich nicht auf. / Heute hast du eine Prüfung. Bist du schon aufgeregt?","en":"It upsets me that I have to do overtime again. / Calm down! Please do not get agitated. / You have an exam today. Are you excited already?"}', '["B1"]', 'verb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"high","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"standard","regionalLabels":[]}', '[]', '["emotions;stress"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":null,"isSeparable":true,"auxiliary":null,"forms":{"presentErSieEs":"haben","praeteritum":"regt auf","partizipII":"regte auf"},"valency":[{"role":"object","preposition":"aufgeregt","case":null}],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["acc, refl, über + acc"]', '{"synonyms":["sich über Kleinigkeiten aufregen"],"antonyms":["empören; ärgern; beunruhigen"],"falseFriends":["beruhigen"],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":88,"url":"https://www.goethe.de"}', 'draft');
